IF DB_ID(N'KaraokeDB') IS NULL CREATE DATABASE KaraokeDB;
GO
USE KaraokeDB;
GO
IF OBJECT_ID(N'dbo.PhongHat',N'U') IS NULL CREATE TABLE dbo.PhongHat(MaPhong INT IDENTITY(1,1) PRIMARY KEY,TenPhong NVARCHAR(50) NOT NULL,LoaiPhong NVARCHAR(30) NOT NULL,GiaTheoGio DECIMAL(18,2) NOT NULL CHECK(GiaTheoGio>=0),TrangThai NVARCHAR(20) NOT NULL CONSTRAINT DF_Phong_Status DEFAULT N'Trống');
IF OBJECT_ID(N'dbo.DichVu',N'U') IS NULL CREATE TABLE dbo.DichVu(MaDV INT IDENTITY(1,1) PRIMARY KEY,TenDV NVARCHAR(100) NOT NULL,DonGia DECIMAL(18,2) NOT NULL CHECK(DonGia>=0),TonKho INT NOT NULL CHECK(TonKho>=0));
IF OBJECT_ID(N'dbo.HoaDon',N'U') IS NULL CREATE TABLE dbo.HoaDon(MaHD INT IDENTITY(1,1) PRIMARY KEY,MaPhong INT NOT NULL REFERENCES dbo.PhongHat(MaPhong),GioVao DATETIME NOT NULL CONSTRAINT DF_HD_GioVao DEFAULT GETDATE(),GioRa DATETIME NULL,TongTienPhong DECIMAL(18,2) NOT NULL CONSTRAINT DF_HD_Phong DEFAULT 0,TongTienDichVu DECIMAL(18,2) NOT NULL CONSTRAINT DF_HD_DV DEFAULT 0,TrangThai BIT NOT NULL CONSTRAINT DF_HD_Status DEFAULT 0);
IF OBJECT_ID(N'dbo.ChiTietDichVu',N'U') IS NULL CREATE TABLE dbo.ChiTietDichVu(MaHD INT NOT NULL REFERENCES dbo.HoaDon(MaHD),MaDV INT NOT NULL REFERENCES dbo.DichVu(MaDV),SoLuong INT NOT NULL CHECK(SoLuong>0),DonGia DECIMAL(18,2) NOT NULL,CONSTRAINT PK_ChiTietDichVu PRIMARY KEY(MaHD,MaDV));
IF NOT EXISTS(SELECT 1 FROM dbo.PhongHat) INSERT dbo.PhongHat(TenPhong,LoaiPhong,GiaTheoGio) VALUES(N'Phòng VIP 01',N'VIP',250000),(N'Phòng VIP 02',N'VIP',250000),(N'Phòng Thường 01',N'Thường',150000),(N'Phòng Thường 02',N'Thường',150000),(N'Phòng Thường 03',N'Thường',150000),(N'Phòng Gia Đình',N'Gia đình',180000);
IF NOT EXISTS(SELECT 1 FROM dbo.DichVu) INSERT dbo.DichVu(TenDV,DonGia,TonKho) VALUES(N'Bia Heineken',35000,48),(N'Trái cây dĩa',85000,20),(N'Nước suối',15000,36),(N'Khăn lạnh',5000,80),(N'Snack khoai tây',30000,25);
